  if(input.dueAtUtc)assertCanonicalUtcTimestamp(input.dueAtUtc,"dueAtUtc");
  const row=this.database.prepare(`SELECT acceptance_state,delivery_state FROM traderlink_community_coaching_trade_reviews WHERE community_id=? AND relationship_id=? AND review_id=?`).get(input.communityId,input.relationshipId,input.reviewId) as {acceptance_state:string;delivery_state:string}|undefined;
