   this.database.prepare(`UPDATE traderlink_community_coaching_trade_reviews SET period_start=?,period_end=?,updated_at_utc=? WHERE review_id=? AND period_start IS NULL AND period_end IS NULL`).run(input.periodStart,input.periodEnd,input.atUtc,input.reviewId);
